MOD = 10**9 + 7

def count_similar_permutations(n, a):
    # Calculate the MEX of the entire array
    mex_values = [False] * (n + 1)
    for num in a:
        if num <= n:
            mex_values[num] = True
    mex = 0
    while mex <= n and mex_values[mex]:
        mex += 1

    # Count the number of permutations similar to a
    dp = [0] * (n + 1)
    dp[mex] = 1

    for i in range(mex, n):
        for j in range(i + 1, n + 1):
            mex_interval = 0
            mex_values = [False] * (n + 1)
            for k in range(i, j):
                mex_values[a[k]] = True
            while mex_values[mex_interval]:
                mex_interval += 1
            if mex_interval == mex:
                dp[mex_interval] = (dp[mex_interval] + dp[i]) % MOD

    result = 0
    for i in range(mex, n + 1):
        result = (result + dp[i]) % MOD

    return result

def main():
    import sys
    input = sys.stdin.read
    data = input().split()

    t = int(data[0])
    index = 1
    results = []

    for _ in range(t):
        n = int(data[index])
        index += 1
        a = list(map(int, data[index:index + n]))
        index += n
        results.append(count_similar_permutations(n, a))

    for result in results:
        print(result)

if __name__ == "__main__":
    main()
